    portugal: {
      netUSD: ptNetEUR * EUR_TO_USD,
      netEUR: ptNetEUR,
      taxUSD: (ptIrs + ptSolidarity + ptSocialSecurity) * EUR_TO_USD,
      irsUSD: ptIrs * EUR_TO_USD,
      solidarityUSD: ptSolidarity * EUR_TO_USD,
      ssUSD: ptSocialSecurity * EUR_TO_USD
    }
